CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.directory_cities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,country text NOT NULL DEFAULT 'ليبيا', UNIQUE(name,country));
GRANT SELECT ON public.directory_cities TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.directory_cities TO authenticated; GRANT ALL ON public.directory_cities TO service_role;
ALTER TABLE public.directory_cities ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_cities ON public.directory_cities FOR SELECT USING(true);
CREATE POLICY admin_cities ON public.directory_cities FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.directory_regions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id uuid NOT NULL REFERENCES public.directory_cities(id),name text NOT NULL,UNIQUE(city_id,name),UNIQUE(id,city_id));
GRANT SELECT ON public.directory_regions TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.directory_regions TO authenticated; GRANT ALL ON public.directory_regions TO service_role;
ALTER TABLE public.directory_regions ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_regions ON public.directory_regions FOR SELECT USING(true);
CREATE POLICY admin_regions ON public.directory_regions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.directory_clinics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id uuid NOT NULL REFERENCES public.directory_cities(id),region_id uuid, name text NOT NULL,kind text NOT NULL DEFAULT 'مصحة' CHECK(kind IN ('مصحة','عيادة','مركز طبي','مستشفى')),address text,phones text[] NOT NULL DEFAULT '{}',specialties text[] NOT NULL DEFAULT '{}',services text[] NOT NULL DEFAULT '{}',latitude double precision,longitude double precision,coordinate_source_url text,source_urls text[] NOT NULL DEFAULT '{}',photo_url text,photo_attribution text,verified_at timestamptz,published boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(region_id,city_id) REFERENCES public.directory_regions(id,city_id), CHECK((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180 AND coordinate_source_url IS NOT NULL)));
GRANT SELECT ON public.directory_clinics TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.directory_clinics TO authenticated; GRANT ALL ON public.directory_clinics TO service_role;
ALTER TABLE public.directory_clinics ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_clinics ON public.directory_clinics FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_clinics ON public.directory_clinics FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX directory_city_idx ON public.directory_clinics(city_id);
CREATE INDEX directory_region_idx ON public.directory_clinics(region_id);